167				 const char *old, const char *new,
168				 const struct ns_common *new_ns)
169	{
170		struct kernfs_node *parent, *kn = NULL;
171		const struct ns_common *old_ns = NULL;
172		int result;
173	
174		if (!kobj)
175			parent = sysfs_root_kn;
176		else
177			parent = kobj->sd;
178	
179		if (targ->sd)
180			old_ns = targ->sd->ns;
181	
182		result = -ENOENT;
183		kn = kernfs_find_and_get_ns(parent, old, old_ns);
184		if (!kn)
185			goto out;
186	
187		result = -EINVAL;
188		if (kernfs_type(kn) != KERNFS_LINK)
189			goto out;
190		if (kn->symlink.target_kn->priv != targ)
191			goto out;
192	
193		result = kernfs_rename_ns(kn, parent, new, new_ns);
194	
195	out:
196		kernfs_put(kn);
197		return result;
198	}
199	EXPORT_SYMBOL_GPL(sysfs_rename_link_ns);
